  "resume": "ヤクザの組長の息子・一条楽と、対立するギャング団のボスの娘・桐崎千棘は、両家の抗争を避けるため恋人同士のふりをさせられる。問題は、二人がお互いを毛嫌いしていることだ。さらに楽は、幼い頃に約束を交わした少女を探している。その証は、彼女が鍵を持つペンダント。ところが、その約束の少女だと名乗る娘が何人も現れ、それぞれ違う鍵を持っていた。本物は誰なのか。",
